/bin/zsh -lc "node <<'NODE'
const fs=require('fs'),crypto=require('crypto');
const request=JSON.parse(fs.readFileSync('.intentfold/tickets/STEMROBIN-182/tmp/batch393-source-glyph-binding/affected-review-request.json','utf8'));
const hash=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
const protectedFindings=request.protected_pages.map(p=>({physical_page:p.physical_page,files:p.files.map(pair=>{const original=fs.readFileSync(pair.original.path),current=fs.readFileSync(pair.current.path);return{file:pair.current.path.split('/').at(-1),original_rawSHA:hash(original),current_rawSHA:hash(current),original_requested_hash_matches:hash(original)===pair.original.raw_sha256,current_requested_hash_matches:hash(current)===pair.current.raw_sha256,same_bytes:original.equals(current)}})}));
console.log(JSON.stringify({protected_pages:protectedFindings},null,2));
const retention=JSON.parse(fs.readFileSync(request.original_retention.path,'utf8'));const collections=Object.entries(retention).filter(([,v])=>Array.isArray(v));for(const [name,entries]of collections){console.log('RETENTION_COLLECTION '+name+' '+entries.length);for(const [index,entry]of entries.entries()){if("'!entry.retained){console.log(JSON.stringify({entry:index+1,value:entry}));continue;}const bytes=fs.readFileSync(entry.retained.path),actual=hash(bytes);console.log(JSON.stringify({entry:index+1,path:entry.retained.path.replace(process.cwd()+'"'/',''),declared_original_rawSHA:entry.original.raw_sha256,declared_retained_rawSHA:entry.retained.raw_sha256,actual_rawSHA:actual,matches:actual===entry.retained.raw_sha256&&actual===entry.original.raw_sha256,content_decoded:false}));}}
const crop=request.figure36.crop_after,bytes=fs.readFileSync(crop.path),actual=hash(bytes);console.log(JSON.stringify({named_crop_hash_only:{path:crop.path,actual_rawSHA:actual,matches_before:actual===request.figure36.crop_before.raw_sha256,matches_after:actual===crop.raw_sha256,content_decoded:false,visual_opens:0}}));
NODE"

