/bin/zsh -lc "node <<'NODE'
const fs=require('fs'),util=require('util');
const request=JSON.parse(fs.readFileSync('.intentfold/tickets/STEMROBIN-182/tmp/batch393-source-glyph-binding/affected-review-request.json','utf8'));
for(const snapshot of request.snapshots){for(const kind of ['original_files','current_files']){const text=fs.readFileSync(snapshot[kind][0].path,'utf8'),json=JSON.parse(fs.readFileSync(snapshot[kind][1].path,'utf8')),rows=text.split('\\n'),end=rows.indexOf('---',1),meta=JSON.parse(rows.slice(1,end).join('\\n'));const headers=rows.map((value,index)=>({value,index})).filter(({value,index})=>index>end&&value.startsWith('<"'!-- '"')&&value.endsWith(' -->'));const blocks=headers.map(({value,index},i)=>{const body=rows.slice(index+1,headers[i+1]?.index??rows.length).filter(line=>line"'!=='"'');const b=json.blocks[i];const expectedHeader="'`<!-- ${b.kind}${b.label?'"' '+b.label:''}"'${b.box?'"' box '+b.box.join(','):''}"'${b.owner_exercise?'"' owner-ex '+b.owner_exercise:''}"'${b.cont?'"' cont':''}"'${b.open?'"' open':''}"'${b.samerow?'"' samerow':''} -->"'`;return{block:i+1,header_agrees:value===expectedHeader,body_agrees:b.kind==='"'fig'?util.isDeepStrictEqual(body,["'`![${b.label}](figures/${b.id}.png)`])&&b.lines.length===0:util.isDeepStrictEqual(body,b.lines)};});console.log(JSON.stringify({physical_page:snapshot.physical_page,kind,meta_agrees:util.isDeepStrictEqual(meta,json.meta),block_count:headers.length,generated_block_count:json.blocks.length,blocks}));}}
const escape=s=>JSON.stringify(s).replace(/['"\\u007f-\\uffff]/g,c=>'\\\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'));
for(const snapshot of request.snapshots){const old=JSON.parse(fs.readFileSync(snapshot.original_files[1].path,'utf8')),now=JSON.parse(fs.readFileSync(snapshot.current_files[1].path,'utf8'));for(const i of snapshot.physical_page===172?[0,1]:[1])console.log("'`PAGE ${snapshot.physical_page} NOTE ${i}'"\\nORIGINAL "'${escape(old.meta.notes[i])}'"\\nCURRENT "'${escape(now.meta.notes[i])}`);for(const [block,line]of snapshot.physical_page===172?[[1,0],[3,4]]:[[2,1]])console.log(`PAGE ${snapshot.physical_page} BLOCK ${block+1} LINE ${line+1}'"\\nORIGINAL "'${escape(old.blocks[block].lines[line])}'"\\nCURRENT "'${escape(now.blocks[block].lines[line])}`);}
NODE'

